#!/usr/bin/env bash
# Create a polished DMG for OpenDesk with:
#   - Applications folder symlink
#   - Custom background image
#   - Proper icon layout via AppleScript
#   - Compressed UDZO format
#
# Usage:
#   bash scripts/create-dmg.sh path/to/opendesk.app [output.dmg]
#
# Prerequisites:
#   - Signed & notarized .app bundle
#   - Background image at resources/dmg-background.png (generated by scripts/generate-dmg-background.py)

set -euo pipefail

APP_PATH="${1:?usage: $0 <path/to/opendesk.app> [output.dmg]}"
APP_NAME="$(basename "${APP_PATH}")"
OUTPUT_DMG="${2:-OpenDesk-$(date +%Y%m%d)-arm64.dmg}"
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
ROOT_DIR="$(cd "${SCRIPT_DIR}/.." && pwd)"
BG_IMAGE="${ROOT_DIR}/resources/dmg-background.png"

[[ -d "${APP_PATH}" ]] || { echo "ERROR: ${APP_PATH} not found" >&2; exit 1; }
[[ -f "${BG_IMAGE}" ]] || {
    echo "WARNING: background image not found at ${BG_IMAGE}"
    echo "         run: python3 scripts/generate-dmg-background.py"
    echo "         continuing without background..."
    BG_IMAGE=""
}

VOLNAME="OpenDesk"
STAGING="$(mktemp -d -t opendesk-dmg.XXXXXX)"
trap 'rm -rf "${STAGING}"' EXIT

echo "=== Creating OpenDesk DMG ==="
echo "  App:      ${APP_PATH}"
echo "  Output:   ${OUTPUT_DMG}"
echo "  Volume:   ${VOLNAME}"

# --- Step 1: Prepare staging directory ---
echo "[1/5] preparing staging directory..."
cp -R "${APP_PATH}" "${STAGING}/"

# Create Applications symlink (localized names for common locales)
ln -s /Applications "${STAGING}/Applications"

# Copy background image into the DMG's hidden .background folder
if [[ -n "${BG_IMAGE}" ]]; then
    mkdir -p "${STAGING}/.background"
    cp "${BG_IMAGE}" "${STAGING}/.background/background.png"
fi

# --- Step 2: Create temporary read-write DMG ---
echo "[2/5] creating temporary DMG..."
# The app bundle is large (~1 GB). Use a fixed 2 GB size for the UDRW
# scratch image so the HFS+ filesystem has enough room for metadata, the hidden
# .background folder, and Finder's .DS_Store.
DMG_SIZE_MB=2048

TEMP_DMG="/tmp/opendesk-temp-$$.dmg"
hdiutil create -volname "${VOLNAME}" \
    -srcfolder "${STAGING}" \
    -size "${DMG_SIZE_MB}m" \
    -fs HFS+ \
    -format UDRW \
    -ov \
    "${TEMP_DMG}" > /dev/null

# --- Step 3: Mount and set layout via AppleScript ---
echo "[3/5] mounting and configuring layout..."

# Try to unmount any leftover mount first
hdiutil detach "/Volumes/${VOLNAME}" 2>/dev/null || true

DEVICE=$(hdiutil attach -readwrite -noverify -noautoopen "${TEMP_DMG}" 2>&1 | grep 'Apple_HFS' | awk '{print $1}')
[[ -n "${DEVICE}" ]] || { echo "ERROR: failed to mount DMG" >&2; exit 1; }

# Wait for Finder to settle
sleep 1

# Use osascript to configure the Finder window
# Window is 660×400 (original size). Background image is 1320×800 (2x) so it
# downscales cleanly on Retina displays.
#   App icon:        left-center  (x=128, y=120)
#   Applications:    right-center (x=436, y=120)
#   Icon size:       96
osascript <<EOF
tell application "Finder"
    tell disk "${VOLNAME}"
        open
        set current view of container window to icon view
        set toolbar visible of container window to false
        set statusbar visible of container window to false
        set the bounds of container window to {390, 250, 1050, 650}
        set viewOptions to the icon view options of container window
        set arrangement of viewOptions to not arranged
        set icon size of viewOptions to 96
        set label position of viewOptions to bottom
        set background picture of viewOptions to file ".background:background.png"
        set position of item "${APP_NAME}" of container window to {165, 120}
        set position of item "Applications" of container window to {495, 120}
        close
        open
        update without registering applications
        delay 1
    end tell
end tell
EOF

# --- Step 4: Finalize and convert ---
echo "[4/5] finalizing DMG..."

# Sync and wait for Finder
sync
sleep 2

# Detach
hdiutil detach "${DEVICE}" -force 2>/dev/null || true
sleep 1

# Convert to compressed UDZO
echo "      converting to compressed UDZO..."
rm -f "${OUTPUT_DMG}"
hdiutil convert "${TEMP_DMG}" -format UDZO -imagekey zlib-level=9 -o "${OUTPUT_DMG}" > /dev/null

# --- Step 5: Cleanup and report ---
echo "[5/5] cleaning up..."
rm -f "${TEMP_DMG}"

echo ""
echo "=== DMG created successfully ==="
echo "  $(ls -lh "${OUTPUT_DMG}" | awk '{print $5, $NF}')"
echo ""
echo "To verify:"
echo "  hdiutil attach '${OUTPUT_DMG}'"
echo "  spctl --assess --type execute /Volumes/${VOLNAME}/${APP_NAME}"
echo "  hdiutil detach /Volumes/${VOLNAME}"
